 void init(XrInstance i,XrSession s,PFN_xrGetInstanceProcAddr g){instance=i;session=s;gipa=g;load("xrSyncActions",sync);load("xrLocateSpace",locate);load("xrGetActionStateFloat",getFloat);load("xrGetActionStateBoolean",getBool);load("xrGetActionStateVector2f",getVector);load("xrGetActionStatePose",getPose);load("xrDestroySpace",destroySpace);load("xrDestroyActionSet",destroySet);hands[0]=path("/user/hand/left");hands[1]=path("/user/hand/right");PFN_xrCreateActionSet create{};load("xrCreateActionSet",create);XrActionSetCreateInfo ci{XR_TYPE_ACTION_SET_CREATE_INFO};strcpy(ci.actionSetName,"alyx_controls");strcpy(ci.localizedActionSetName,"Alyx controllers");check(create(instance,&ci,&set),"controller action set");pose=action("hand_pose",XR_ACTION_TYPE_POSE_INPUT);trigger=action("trigger",XR_ACTION_TYPE_FLOAT_INPUT);grip=action("grip",XR_ACTION_TYPE_FLOAT_INPUT);stick=action("stick",XR_ACTION_TYPE_VECTOR2F_INPUT);primary=action("primary",XR_ACTION_TYPE_BOOLEAN_INPUT);secondary=action("secondary",XR_ACTION_TYPE_BOOLEAN_INPUT);click=action("stick_click",XR_ACTION_TYPE_BOOLEAN_INPUT);touch=action("stick_touch",XR_ACTION_TYPE_BOOLEAN_INPUT);menu=action("menu",XR_ACTION_TYPE_BOOLEAN_INPUT);triggerTouch=action("trigger_touch",XR_ACTION_TYPE_BOOLEAN_INPUT);primaryTouch=action("primary_touch",XR_ACTION_TYPE_BOOLEAN_INPUT);secondaryTouch=action("secondary_touch",XR_ACTION_TYPE_BOOLEAN_INPUT);thumbrestTouch=action("thumbrest_touch",XR_ACTION_TYPE_BOOLEAN_INPUT);
 std::vector<XrActionSuggestedBinding> bindings;auto bind=[&](XrAction a,const char* h,const char* component){char buf[160];snprintf(buf,sizeof(buf),"/user/hand/%s/input/%s",h,component);bindings.push_back({a,path(buf)});};for(const char* h:{"left","right"}){bind(pose,h,"grip/pose");bind(trigger,h,"trigger/value");bind(grip,h,"squeeze/value");bind(stick,h,"thumbstick");bind(click,h,"thumbstick/click");bind(touch,h,"thumbstick/touch");bind(triggerTouch,h,"trigger/touch");bind(thumbrestTouch,h,"thumbrest/touch");}bind(primary,"left","x/click");bind(secondary,"left","y/click");bind(primary,"right","a/click");bind(secondary,"right","b/click");bind(menu,"left","menu/click");bind(primaryTouch,"left","x/touch");bind(secondaryTouch,"left","y/touch");bind(primaryTouch,"right","a/touch");bind(secondaryTouch,"right","b/touch");PFN_xrSuggestInteractionProfileBindings suggest{};load("xrSuggestInteractionProfileBindings",suggest);XrInteractionProfileSuggestedBinding sb{XR_TYPE_INTERACTION_PROFILE_SUGGESTED_BINDING};sb.interactionProfile=path("/interaction_profiles/oculus/touch_controller");sb.countSuggestedBindings=bindings.size();sb.suggestedBindings=bindings.data();check(suggest(instance,&sb),"Touch controller bindings");PFN_xrCreateActionSpace createSpace{};load("xrCreateActionSpace",createSpace);for(int h=0;h<2;h++){XrActionSpaceCreateInfo ai{XR_TYPE_ACTION_SPACE_CREATE_INFO};ai.action=pose;ai.subactionPath=hands[h];ai.poseInActionSpace.orientation.w=1;check(createSpace(session,&ai,&spaces[h]),"controller space");}PFN_xrAttachSessionActionSets attach{};load("xrAttachSessionActionSets",attach);XrSessionActionSetsAttachInfo at{XR_TYPE_SESSION_ACTION_SETS_ATTACH_INFO};at.countActionSets=1;at.actionSets=&set;check(attach(session,&at),"attach controllers");puts("Controllers: Touch grip poses, trigger/grip, sticks, A/B/X/Y and menu attached.");}
